steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "{
      users(query: \"Leo Park\") {
        nodes {
          id
          name
          displayName
        }
      }
      issue(identifier: \"WEB-1\") {
        id
        identifier
        title
        url
      }
    }"
  }'
